-- Links the price sources the guides already name (Humble & Brag, MarketerHire) to their pages,
-- on the existing words only, and sets the author photo (public/team/waris-jamil.png). Each guide
-- is changed only while it still has the same number of links to that source as before.

begin;

-- youtube-agency
update guides set
  body_json = $g${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A YouTube agency is a company that grows a business or creator on YouTube for a fee. Depending on the agency, that means running YouTube ads, making videos, optimizing them for search, or managing the whole channel from strategy to monthly reports."}]},{"type":"paragraph","content":[{"type":"text","text":"Most YouTube agencies focus on one or two of those jobs. A clinic that wants new patients from ads needs a different agency than a creator who wants an editor and a thumbnail designer. Knowing which type you need is most of the work of hiring one."}]},{"type":"paragraph","content":[{"type":"text","text":"This guide covers what YouTube agencies do, the six main types, how they compare with freelancers and in-house teams, and what they cost."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What a YouTube agency does day to day"}]},{"type":"paragraph","content":[{"type":"text","text":"The work varies by agency, but it usually falls into five areas:"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Strategy. Deciding who the channel or ads are for, which topics to cover, and which numbers count as success (leads, sales, subscribers or watch time)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Content. Writing scripts, filming, editing, and designing thumbnails and titles."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Optimization. Researching what people search for on YouTube, then writing titles, descriptions, chapters and tags that match."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Distribution. Running YouTube ads, cutting long videos into Shorts, and arranging creator partnerships."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reporting. A monthly report on what grew, what didn't, and what changes next month."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A small agency might do only items 2 and 3 for creators. A paid-media agency might do only 1, 4 and 5 for businesses that already have videos. Full-service agencies cover all five."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The six main types of YouTube agencies"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Type"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"What they do"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Who hires them"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Typical result they're judged on"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"YouTube ads agency"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ad scripts, targeting, conversion tracking, budget management"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Businesses selling a product or service"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Cost per lead, return on ad spend"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"YouTube SEO agency"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Keyword research, titles, descriptions, topic planning"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Businesses and creators who want search traffic"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Views from search, ranking for target terms"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Channel management agency"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Strategy, uploads, optimization and monthly reporting"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Busy owners who want the channel handled"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Subscriber and watch-time growth, leads"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Video production agency"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Scripts, filming and editing"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Brands without in-house video skills"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Finished videos on time and on brief"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Influencer marketing agency"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Finds creators, negotiates deals, manages sponsored videos"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Brands that want to reach an existing audience"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Cost per acquisition from sponsored videos"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Creator or talent management (including MCNs)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Brand deals, rights management, career support for creators"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Creators, especially once they have an audience"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sponsorship income, channel revenue"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"There are also narrower specialists: "},{"type":"text","text":"video editing"},{"type":"text","text":", "},{"type":"text","text":"scriptwriting"},{"type":"text","text":", "},{"type":"text","text":"thumbnails and packaging"},{"type":"text","text":", "},{"type":"text","text":"Shorts"},{"type":"text","text":" and "},{"type":"text","text":"channel audits"},{"type":"text","text":". These are useful when one weak spot is holding a channel back, for example low click-through rates from weak thumbnails."}]},{"type":"paragraph","content":[{"type":"text","text":"The first five types mostly work for businesses. The sixth works for creators, and it's the one people usually mean by a \"YouTuber agency\". It often takes a share of the creator's income instead of a monthly fee."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"YouTube agency vs freelancer vs in-house team"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Option"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Monthly cost"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Strengths"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Weak spots"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Freelancer"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Often $500 to $3,000"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Cheap, flexible, good for one skill like editing or thumbnails"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"One person, so holidays and sick days stop the work; you manage the strategy"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Agency"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Often $1,000 to $10,000+"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Several skills under one contract, a process, someone accountable for results"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Costs more; you may get a junior team after the pitch"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"In-house team"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$6,000+ for even one full-time editor"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Knows your business best, fastest turnaround"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Hiring takes months; one editor rarely covers strategy, ads and design"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The in-house figure is based on US wages: the mean pay for film and video editors is around $77,000 a year, per MarketerHire's reading of Bureau of Labor Statistics data. The same source suggests building in-house only once you spend $30,000 or more a month on YouTube and publish weekly."}]},{"type":"paragraph","content":[{"type":"text","text":"A common path is freelancer first, agency once YouTube is bringing in money, then in-house once the channel is a core sales channel."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How YouTube agencies charge"}]},{"type":"paragraph","content":[{"type":"text","text":"Most charge one of four ways: a flat monthly retainer, a percentage of ad spend (ads agencies only), a price per video or project, or a share of revenue (common with creator management)."}]},{"type":"paragraph","content":[{"type":"text","text":"Rough monthly ranges by type, drawn from "},{"type":"text","text":"published agency pricing guides","marks":[{"type":"link","attrs":{"href":"https://humbleandbrag.com/blog/youtube-agency-cost"}}]},{"type":"text","text":"."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Type"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Typical monthly fee"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Titles and thumbnails only"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$500 to $2,000"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Video production or editing"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$2,000 to $5,000"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"YouTube SEO and optimization"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$3,000 to $8,000"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"YouTube ads management"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$1,000 to $12,000, plus ad spend"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Full-service growth"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$10,000 to $30,000"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Humble & Brag","marks":[{"type":"link","attrs":{"href":"https://humbleandbrag.com/blog/youtube-agency-cost"}}]},{"type":"text","text":" publishes its ranges in euros; the dollar figures above round them. Many agencies we reviewed start around $1,000. For a detailed breakdown of ads pricing, see our guide to "},{"type":"text","text":"YouTube ads agency costs","marks":[{"type":"link","attrs":{"href":"https://ytagencies.com/guides/youtube-ads-agency-cost"}}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How to pick the right YouTube agency"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Name the one result you want. \"More leads from YouTube ads\" points to an ads agency. \"A channel that posts every week without me\" points to channel management."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Shortlist agencies that have worked in your industry. A dental clinic and a gaming creator need very different hooks, thumbnails and targeting."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ask for case studies with real numbers and links to the channels, then check those channels yourself. Look at views per video over time, not subscriber count."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compare at least three quotes on the same terms: fee, what's included, minimum contract, and who owns the channel and ad account."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Start small. A one to three month trial tells you more than any sales call."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"FAQ"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"What does a YouTube agency do?"}]},{"type":"paragraph","content":[{"type":"text","text":"It grows a channel or business on YouTube through some mix of strategy, video production, optimization, ads and reporting. Most agencies specialize in one or two of these."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Is a YouTube agency the same as an MCN?"}]},{"type":"paragraph","content":[{"type":"text","text":"No. An MCN (multi-channel network) is a type of creator management company that partners with many channels, usually for a share of their revenue. Most YouTube agencies work for businesses and charge a fee."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Do YouTube agencies work with small channels?"}]},{"type":"paragraph","content":[{"type":"text","text":"Many do, especially editing, thumbnail and channel audit specialists. Ads agencies usually want a minimum ad budget, so very small businesses may be better off starting with a freelancer."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"How long does it take to see results?"}]},{"type":"paragraph","content":[{"type":"text","text":"Ads can show early data within weeks. Organic growth from SEO and regular uploads usually takes three to six months to judge."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Is YT Agencies a YouTube agency?"}]},{"type":"paragraph","content":[{"type":"text","text":"No. YT Agencies is an independent publication of YouTube guides. It isn't affiliated with YouTube or Google."}]}]}$g$::jsonb,
  body_html = $g$<p>A YouTube agency is a company that grows a business or creator on YouTube for a fee. Depending on the agency, that means running YouTube ads, making videos, optimizing them for search, or managing the whole channel from strategy to monthly reports.</p><p>Most YouTube agencies focus on one or two of those jobs. A clinic that wants new patients from ads needs a different agency than a creator who wants an editor and a thumbnail designer. Knowing which type you need is most of the work of hiring one.</p><p>This guide covers what YouTube agencies do, the six main types, how they compare with freelancers and in-house teams, and what they cost.</p><h2>What a YouTube agency does day to day</h2><p>The work varies by agency, but it usually falls into five areas:</p><ol><li><p>Strategy. Deciding who the channel or ads are for, which topics to cover, and which numbers count as success (leads, sales, subscribers or watch time).</p></li><li><p>Content. Writing scripts, filming, editing, and designing thumbnails and titles.</p></li><li><p>Optimization. Researching what people search for on YouTube, then writing titles, descriptions, chapters and tags that match.</p></li><li><p>Distribution. Running YouTube ads, cutting long videos into Shorts, and arranging creator partnerships.</p></li><li><p>Reporting. A monthly report on what grew, what didn't, and what changes next month.</p></li></ol><p>A small agency might do only items 2 and 3 for creators. A paid-media agency might do only 1, 4 and 5 for businesses that already have videos. Full-service agencies cover all five.</p><h2>The six main types of YouTube agencies</h2><table><thead><tr><th>Type</th><th>What they do</th><th>Who hires them</th><th>Typical result they're judged on</th></tr></thead><tbody><tr><td>YouTube ads agency</td><td>Ad scripts, targeting, conversion tracking, budget management</td><td>Businesses selling a product or service</td><td>Cost per lead, return on ad spend</td></tr><tr><td>YouTube SEO agency</td><td>Keyword research, titles, descriptions, topic planning</td><td>Businesses and creators who want search traffic</td><td>Views from search, ranking for target terms</td></tr><tr><td>Channel management agency</td><td>Strategy, uploads, optimization and monthly reporting</td><td>Busy owners who want the channel handled</td><td>Subscriber and watch-time growth, leads</td></tr><tr><td>Video production agency</td><td>Scripts, filming and editing</td><td>Brands without in-house video skills</td><td>Finished videos on time and on brief</td></tr><tr><td>Influencer marketing agency</td><td>Finds creators, negotiates deals, manages sponsored videos</td><td>Brands that want to reach an existing audience</td><td>Cost per acquisition from sponsored videos</td></tr><tr><td>Creator or talent management (including MCNs)</td><td>Brand deals, rights management, career support for creators</td><td>Creators, especially once they have an audience</td><td>Sponsorship income, channel revenue</td></tr></tbody></table><p>There are also narrower specialists: video editing, scriptwriting, thumbnails and packaging, Shorts and channel audits. These are useful when one weak spot is holding a channel back, for example low click-through rates from weak thumbnails.</p><p>The first five types mostly work for businesses. The sixth works for creators, and it's the one people usually mean by a "YouTuber agency". It often takes a share of the creator's income instead of a monthly fee.</p><h2>YouTube agency vs freelancer vs in-house team</h2><table><thead><tr><th>Option</th><th>Monthly cost</th><th>Strengths</th><th>Weak spots</th></tr></thead><tbody><tr><td>Freelancer</td><td>Often $500 to $3,000</td><td>Cheap, flexible, good for one skill like editing or thumbnails</td><td>One person, so holidays and sick days stop the work; you manage the strategy</td></tr><tr><td>Agency</td><td>Often $1,000 to $10,000+</td><td>Several skills under one contract, a process, someone accountable for results</td><td>Costs more; you may get a junior team after the pitch</td></tr><tr><td>In-house team</td><td>$6,000+ for even one full-time editor</td><td>Knows your business best, fastest turnaround</td><td>Hiring takes months; one editor rarely covers strategy, ads and design</td></tr></tbody></table><p>The in-house figure is based on US wages: the mean pay for film and video editors is around $77,000 a year, per MarketerHire's reading of Bureau of Labor Statistics data. The same source suggests building in-house only once you spend $30,000 or more a month on YouTube and publish weekly.</p><p>A common path is freelancer first, agency once YouTube is bringing in money, then in-house once the channel is a core sales channel.</p><h2>How YouTube agencies charge</h2><p>Most charge one of four ways: a flat monthly retainer, a percentage of ad spend (ads agencies only), a price per video or project, or a share of revenue (common with creator management).</p><p>Rough monthly ranges by type, drawn from <a href="https://humbleandbrag.com/blog/youtube-agency-cost">published agency pricing guides</a>.</p><table><thead><tr><th>Type</th><th>Typical monthly fee</th></tr></thead><tbody><tr><td>Titles and thumbnails only</td><td>$500 to $2,000</td></tr><tr><td>Video production or editing</td><td>$2,000 to $5,000</td></tr><tr><td>YouTube SEO and optimization</td><td>$3,000 to $8,000</td></tr><tr><td>YouTube ads management</td><td>$1,000 to $12,000, plus ad spend</td></tr><tr><td>Full-service growth</td><td>$10,000 to $30,000</td></tr></tbody></table><p><a href="https://humbleandbrag.com/blog/youtube-agency-cost">Humble &amp; Brag</a> publishes its ranges in euros; the dollar figures above round them. Many agencies we reviewed start around $1,000. For a detailed breakdown of ads pricing, see our guide to <a href="https://ytagencies.com/guides/youtube-ads-agency-cost">YouTube ads agency costs</a>.</p><h2>How to pick the right YouTube agency</h2><ol><li><p>Name the one result you want. "More leads from YouTube ads" points to an ads agency. "A channel that posts every week without me" points to channel management.</p></li><li><p>Shortlist agencies that have worked in your industry. A dental clinic and a gaming creator need very different hooks, thumbnails and targeting.</p></li><li><p>Ask for case studies with real numbers and links to the channels, then check those channels yourself. Look at views per video over time, not subscriber count.</p></li><li><p>Compare at least three quotes on the same terms: fee, what's included, minimum contract, and who owns the channel and ad account.</p></li><li><p>Start small. A one to three month trial tells you more than any sales call.</p></li></ol><h2>FAQ</h2><h3>What does a YouTube agency do?</h3><p>It grows a channel or business on YouTube through some mix of strategy, video production, optimization, ads and reporting. Most agencies specialize in one or two of these.</p><h3>Is a YouTube agency the same as an MCN?</h3><p>No. An MCN (multi-channel network) is a type of creator management company that partners with many channels, usually for a share of their revenue. Most YouTube agencies work for businesses and charge a fee.</p><h3>Do YouTube agencies work with small channels?</h3><p>Many do, especially editing, thumbnail and channel audit specialists. Ads agencies usually want a minimum ad budget, so very small businesses may be better off starting with a freelancer.</p><h3>How long does it take to see results?</h3><p>Ads can show early data within weeks. Organic growth from SEO and regular uploads usually takes three to six months to judge.</p><h3>Is YT Agencies a YouTube agency?</h3><p>No. YT Agencies is an independent publication of YouTube guides. It isn't affiliated with YouTube or Google.</p>$g$,
  content_updated_at = now()
where slug = 'youtube-agency'
  and (length(body_json::text) - length(replace(body_json::text, 'https://humbleandbrag.com/blog/youtube-agency-cost', ''))) / 50 = 0;

-- youtube-channel-management-agency-cost
update guides set
  body_json = $g${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A YouTube channel management agency usually costs $1,000 to $5,000 a month for a small business or creator, and $5,000 to $10,000 or more for a full-service team that plans, edits, optimizes and reports on several videos a week."}]},{"type":"paragraph","content":[{"type":"text","text":"In our October 2026 review of publicly listed agency prices, most channel management agencies started at around $1,000 a month on a monthly retainer. What you pay above that depends mostly on how many videos a month the agency handles and whether filming is included."}]},{"type":"paragraph","content":[{"type":"text","text":"Unlike YouTube ads, there's no second bill for ad spend. The retainer is usually the whole cost, plus any production extras."}]},{"type":"paragraph","content":[{"type":"text","text":"A $1,000 starting price is an entry package. Expect it to cover a small number of videos a month with editing, thumbnails and upload optimization. Ask each agency exactly what their entry tier includes before comparing."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Price tiers and what you get"}]},{"type":"paragraph","content":[{"type":"text","text":"Published agency price guides put channel work in roughly these bands ("},{"type":"text","text":"Humble & Brag","marks":[{"type":"link","attrs":{"href":"https://humbleandbrag.com/blog/youtube-agency-cost"}}]},{"type":"text","text":", "},{"type":"text","text":"MarketerHire","marks":[{"type":"link","attrs":{"href":"https://marketerhire.com/blog/youtube-video-marketing-agency"}}]},{"type":"text","text":"):"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Tier"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Typical monthly cost"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"What's usually included"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Packaging only"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$500 to $2,000"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Titles and thumbnails, sometimes A/B testing"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Editing and upload"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$2,000 to $5,000"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Editing of your footage, thumbnails, descriptions, scheduling"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Growth management"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$3,000 to $8,000"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Strategy, topic research, SEO, editing, Shorts, monthly reporting"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Full service"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$10,000 to $30,000"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"All of the above plus scripting, filming days, community management and often ads"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Humble & Brag","marks":[{"type":"link","attrs":{"href":"https://humbleandbrag.com/blog/youtube-agency-cost"}}]},{"type":"text","text":" publishes its tiers in euros; the dollar figures treat them as roughly equal. These ranges overlap because agencies bundle services differently, so compare what's included, not the tier name."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"A rough rule: cost per video"}]},{"type":"paragraph","content":[{"type":"text","text":"Divide the monthly fee by the number of finished videos. A $3,000 retainer for four long videos and eight Shorts works out to $750 per long video, with the Shorts and strategy included. This number makes very different packages easier to compare."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What drives the price up or down"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Number of videos a month. The biggest factor by far."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Who films. Editing your footage is cheap; sending a crew is not. On-location shoot days often cost $2,000 to $5,000 each on top of the retainer."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Video length and editing style. A 30-minute podcast edit costs more than a 6-minute talking-head video; heavy motion graphics cost more again."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Strategy depth. Topic research, competitor analysis and testing titles add senior time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your niche. Finance, B2B and medical channels need more research and review, so agencies often charge more."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Team seniority. Ask who actually works on your channel day to day."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Costs that aren't in the headline price"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Onboarding or setup fees in the first month"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Extra revision rounds beyond what the package includes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stock footage and music licences"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Filming days and travel"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ad spend, if the agency also runs YouTube ads (see our "},{"type":"text","text":"YouTube ads agency cost guide","marks":[{"type":"link","attrs":{"href":"https://ytagencies.com/guides/youtube-ads-agency-cost"}}]},{"type":"text","text":")"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Is channel management worth it?"}]},{"type":"paragraph","content":[{"type":"text","text":"It usually is when YouTube already brings in customers or income and the work is eating your week. Add up the hours you spend planning, editing and uploading each month and multiply by what your time is worth. If that's more than the retainer, hiring makes sense."}]},{"type":"paragraph","content":[{"type":"text","text":"It usually isn't when you have fewer than 10 videos, no clear audience yet, or can't commit for three months. Start with a freelance editor or a one-off "},{"type":"text","text":"channel audit"},{"type":"text","text":" instead."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"FAQ"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"How much does a YouTube manager cost per month?"}]},{"type":"paragraph","content":[{"type":"text","text":"A freelance YouTube manager often charges $500 to $3,000 a month. Most agencies we reviewed start at around $1,000 a month and rise with the number of videos and services."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Do channel management agencies take a percentage of revenue?"}]},{"type":"paragraph","content":[{"type":"text","text":"Most charge a flat monthly fee. Some creator-focused agencies take a share of channel revenue or brand deals instead; read the contract to see which income it covers."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Is there a minimum contract?"}]},{"type":"paragraph","content":[{"type":"text","text":"It varies, so check the contract before you sign."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"What should a channel management package include?"}]},{"type":"paragraph","content":[{"type":"text","text":"At minimum: editing, thumbnails, titles and descriptions, scheduling, and a monthly report. Better packages add topic research, Shorts and a clear plan for next month."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Who owns the channel if I hire an agency?"}]},{"type":"paragraph","content":[{"type":"text","text":"You should. Give the agency access through YouTube Studio permissions, never your password, and keep the owner role yourself."}]}]}$g$::jsonb,
  body_html = $g$<p>A YouTube channel management agency usually costs $1,000 to $5,000 a month for a small business or creator, and $5,000 to $10,000 or more for a full-service team that plans, edits, optimizes and reports on several videos a week.</p><p>In our October 2026 review of publicly listed agency prices, most channel management agencies started at around $1,000 a month on a monthly retainer. What you pay above that depends mostly on how many videos a month the agency handles and whether filming is included.</p><p>Unlike YouTube ads, there's no second bill for ad spend. The retainer is usually the whole cost, plus any production extras.</p><p>A $1,000 starting price is an entry package. Expect it to cover a small number of videos a month with editing, thumbnails and upload optimization. Ask each agency exactly what their entry tier includes before comparing.</p><h2>Price tiers and what you get</h2><p>Published agency price guides put channel work in roughly these bands (<a href="https://humbleandbrag.com/blog/youtube-agency-cost">Humble &amp; Brag</a>, <a href="https://marketerhire.com/blog/youtube-video-marketing-agency">MarketerHire</a>):</p><table><thead><tr><th>Tier</th><th>Typical monthly cost</th><th>What's usually included</th></tr></thead><tbody><tr><td>Packaging only</td><td>$500 to $2,000</td><td>Titles and thumbnails, sometimes A/B testing</td></tr><tr><td>Editing and upload</td><td>$2,000 to $5,000</td><td>Editing of your footage, thumbnails, descriptions, scheduling</td></tr><tr><td>Growth management</td><td>$3,000 to $8,000</td><td>Strategy, topic research, SEO, editing, Shorts, monthly reporting</td></tr><tr><td>Full service</td><td>$10,000 to $30,000</td><td>All of the above plus scripting, filming days, community management and often ads</td></tr></tbody></table><p><a href="https://humbleandbrag.com/blog/youtube-agency-cost">Humble &amp; Brag</a> publishes its tiers in euros; the dollar figures treat them as roughly equal. These ranges overlap because agencies bundle services differently, so compare what's included, not the tier name.</p><h3>A rough rule: cost per video</h3><p>Divide the monthly fee by the number of finished videos. A $3,000 retainer for four long videos and eight Shorts works out to $750 per long video, with the Shorts and strategy included. This number makes very different packages easier to compare.</p><h2>What drives the price up or down</h2><ul><li><p>Number of videos a month. The biggest factor by far.</p></li><li><p>Who films. Editing your footage is cheap; sending a crew is not. On-location shoot days often cost $2,000 to $5,000 each on top of the retainer.</p></li><li><p>Video length and editing style. A 30-minute podcast edit costs more than a 6-minute talking-head video; heavy motion graphics cost more again.</p></li><li><p>Strategy depth. Topic research, competitor analysis and testing titles add senior time.</p></li><li><p>Your niche. Finance, B2B and medical channels need more research and review, so agencies often charge more.</p></li><li><p>Team seniority. Ask who actually works on your channel day to day.</p></li></ul><h2>Costs that aren't in the headline price</h2><ul><li><p>Onboarding or setup fees in the first month</p></li><li><p>Extra revision rounds beyond what the package includes</p></li><li><p>Stock footage and music licences</p></li><li><p>Filming days and travel</p></li><li><p>Ad spend, if the agency also runs YouTube ads (see our <a href="https://ytagencies.com/guides/youtube-ads-agency-cost">YouTube ads agency cost guide</a>)</p></li></ul><h2>Is channel management worth it?</h2><p>It usually is when YouTube already brings in customers or income and the work is eating your week. Add up the hours you spend planning, editing and uploading each month and multiply by what your time is worth. If that's more than the retainer, hiring makes sense.</p><p>It usually isn't when you have fewer than 10 videos, no clear audience yet, or can't commit for three months. Start with a freelance editor or a one-off channel audit instead.</p><h2>FAQ</h2><h3>How much does a YouTube manager cost per month?</h3><p>A freelance YouTube manager often charges $500 to $3,000 a month. Most agencies we reviewed start at around $1,000 a month and rise with the number of videos and services.</p><h3>Do channel management agencies take a percentage of revenue?</h3><p>Most charge a flat monthly fee. Some creator-focused agencies take a share of channel revenue or brand deals instead; read the contract to see which income it covers.</p><h3>Is there a minimum contract?</h3><p>It varies, so check the contract before you sign.</p><h3>What should a channel management package include?</h3><p>At minimum: editing, thumbnails, titles and descriptions, scheduling, and a monthly report. Better packages add topic research, Shorts and a clear plan for next month.</p><h3>Who owns the channel if I hire an agency?</h3><p>You should. Give the agency access through YouTube Studio permissions, never your password, and keep the owner role yourself.</p>$g$,
  content_updated_at = now()
where slug = 'youtube-channel-management-agency-cost'
  and (length(body_json::text) - length(replace(body_json::text, 'https://humbleandbrag.com/blog/youtube-agency-cost', ''))) / 50 = 1;

-- youtube-ads-agency-cost
update guides set
  body_json = $g${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A YouTube ads agency usually costs $1,000 to $5,000 a month for a small or mid-sized business. That is the agency's fee only. The money you spend on the ads themselves is a separate bill paid to Google."}]},{"type":"paragraph","content":[{"type":"text","text":"In our October 2026 review of publicly listed agency prices, most YouTube ads agencies started between $1,000 and $3,000. Agencies that bill as a share of your budget usually take 10% to 20% of monthly ad spend, and some YouTube specialists quote 15% to 25%."}]},{"type":"paragraph","content":[{"type":"text","text":"Bigger brands that want strategy, ad production and testing in one package often pay $5,000 to $12,000 or more a month on top of ad spend."}]},{"type":"paragraph","content":[{"type":"text","text":"Your own number depends on three things: how the agency charges, how much you plan to spend on ads, and whether you need them to make the videos. Each one is covered below, followed by three sample budgets you can copy."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"You pay two bills: the agency and Google"}]},{"type":"paragraph","content":[{"type":"text","text":"Every YouTube ads budget splits into two parts. The first is the agency's fee for strategy, setup, targeting, testing and reporting. The second is your ad spend, which goes straight to Google Ads, usually charged to your own card or invoice."}]},{"type":"paragraph","content":[{"type":"text","text":"This is where most quotes get confusing. One agency says \"$1,500 a month\" and means the fee only. Another says \"$5,000 a month\" and means fee plus ad spend combined. Before you compare two quotes, ask each agency to split them."}]},{"type":"paragraph","content":[{"type":"text","text":"A few agencies buy the media for you and bill you one total. That can work, but ask to see the Google Ads invoices. Otherwise you can't tell how much of your money reached YouTube."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The four ways YouTube ads agencies charge"}]},{"type":"paragraph","content":[{"type":"text","text":"Most agencies use one of four pricing models. Flat monthly retainers are by far the most common. In a "},{"type":"text","text":"Credo survey","marks":[{"type":"link","attrs":{"href":"https://www.getcredo.com/guide/digital-marketing-industry-pricing-survey/ppc-pricing/"}}]},{"type":"text","text":" of 146 firms that run paid ads, about 83% billed a flat retainer and about 13% billed only a percentage of spend."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Model"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"How it works"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Typical range"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Best for"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Flat monthly retainer"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Same fee every month, whatever you spend"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$1,000 to $5,000 a month for most small and mid-sized accounts"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Steady budgets, businesses that want a predictable bill"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Percentage of ad spend"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Fee is a share of what you spend that month"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"10% to 20% of spend, often with a minimum of about $500"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Accounts spending $10,000+ a month that plan to scale"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Hybrid"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"A base fee plus a smaller percentage"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Example: $1,000 base plus 5% of spend"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Budgets that change a lot month to month"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Per project or per video"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"One price for a campaign launch or each ad video"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$1,000 to $3,000 per project; $1,500 to $10,000 per produced video"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"One-off launches, testing an agency before a retainer"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Ranges come from "},{"type":"text","text":"Clicksgeek","marks":[{"type":"link","attrs":{"href":"https://clicksgeek.com/?p=17034"}}]},{"type":"text","text":", "},{"type":"text","text":"MarketerHire","marks":[{"type":"link","attrs":{"href":"https://marketerhire.com/blog/youtube-video-marketing-agency"}}]},{"type":"text","text":" and our October 2026 review of agency prices."}]},{"type":"paragraph","content":[{"type":"text","text":"Performance pricing exists too, where the agency is paid per lead or per sale. It is rare for YouTube because video ads often drive sales that show up later through search or direct visits, which makes the credit hard to agree on."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Flat fee or percentage: the break-even point"}]},{"type":"paragraph","content":[{"type":"text","text":"To compare a flat quote with a percentage quote, divide the flat fee by the percentage:"}]},{"type":"codeBlock","content":[{"type":"text","text":"\\text{Break-even ad spend} = \\frac{\\text{flat monthly fee}}{\\text{percentage rate}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Say Agency A quotes $1,500 a month and Agency B quotes 15% of spend. $1,500 divided by 0.15 is $10,000. Below $10,000 a month in ad spend, Agency B costs less. Above it, Agency A does."}]},{"type":"paragraph","content":[{"type":"text","text":"Keep one thing in mind with percentage pricing: the agency earns more when you spend more, whether or not the extra spend is profitable. That doesn't make it a bad model, but it means you should agree on a target cost per lead or return on ad spend before you raise the budget."}]},{"type":"paragraph","content":[{"type":"text","text":"Starting prices are a floor. Your quote will rise with ad spend, the number of ad videos you need, and how many campaigns run at once. For a wider sample, "},{"type":"text","text":"Clutch","marks":[{"type":"link","attrs":{"href":"https://clutch.co/agencies/ppc/youtube"}}]},{"type":"text","text":" reports minimum project sizes from $1,000 to over $50,000 across thousands of YouTube advertising firms, with $100 to $149 an hour as the most common rate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What the ads themselves cost"}]},{"type":"paragraph","content":[{"type":"text","text":"YouTube ads are usually cheap per view. Across industries, the average cost per view is about $0.026 and the average cost per 1,000 impressions is about $3.53, according to Mega Digital's benchmark data. Competitive niches cost more: healthcare and insurance had the highest average view cost in the same data, at $0.071."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ad format"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"How you pay"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Typical cost"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Skippable in-stream"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Per view (30 seconds watched, the full ad if shorter, or a click)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$0.02 to $0.30 per view"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Non-skippable in-stream"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Per 1,000 impressions"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$6 to $10 CPM"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Bumper (6 seconds)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Per 1,000 impressions"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$10 to $20 CPM"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"In-feed video"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Per view (thumbnail click)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"About $0.10 per view"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Shorts"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Per 1,000 impressions"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"About $4 CPM"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Masthead (top of homepage)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Reserved through Google sales"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$300,000 to $1M+"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Sources: "},{"type":"text","text":"Mega Digital cost guide","marks":[{"type":"link","attrs":{"href":"https://megadigital.ai/en/blog/youtube-ads-cost"}}]},{"type":"text","text":", "},{"type":"text","text":"JoinBrands","marks":[{"type":"link","attrs":{"href":"https://joinbrands.com/blog/how-much-do-youtube-ads-cost/"}}]},{"type":"text","text":", "},{"type":"text","text":"Top Growth Marketing","marks":[{"type":"link","attrs":{"href":"https://topgrowthmarketing.com/youtube-ads-cost/"}}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"What most small businesses actually spend is modest. In a "},{"type":"text","text":"WebFX survey","marks":[{"type":"link","attrs":{"href":"https://www.webfx.com/social-media/pricing/how-much-does-youtube-advertising-cost"}}]},{"type":"text","text":" of 270 marketers, 53% of businesses spent between $101 and $1,000 a month on YouTube ads."}]},{"type":"paragraph","content":[{"type":"text","text":"A cheap view isn't automatically a good one. Work backward from what a customer is worth. If you can afford to pay $40 to win a customer and 0.5% of viewers convert, you can pay up to $0.20 a view and still make your target."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Three sample monthly budgets"}]},{"type":"paragraph","content":[{"type":"text","text":"These are worked examples built from the ranges above, not quotes. Use them to sanity-check what an agency sends you."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Scenario"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ad spend"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Agency fee"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ad videos"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Total per month"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Local business testing YouTube (clinic, law firm, trades)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$1,500"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$1,000 flat retainer"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Uses one existing video"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$2,500"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Growing e-commerce or SaaS brand"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$10,000"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$1,500 (15% of spend)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"2 new ads at about $1,000 each"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$13,500"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Established brand running several campaigns"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$50,000"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$4,500 (hybrid: $2,000 base plus 5%)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"About $5,000 of new creative"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"$59,500"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"In the first scenario, the agency fee is two-thirds of the ad spend. That ratio is normal for small tests, but it means you're mostly paying for setup and learning. Plan to run it for at least three months before you judge results."}]},{"type":"paragraph","content":[{"type":"text","text":"In the third, the fee is under 10% of the total. Past a certain size, the cost that matters most is ad spend that isn't working, so the agency's testing process matters more than its fee."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Extra costs to ask about"}]},{"type":"paragraph","content":[{"type":"text","text":"The monthly fee rarely covers everything. Ask each agency whether these are included:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Setup or onboarding fees in the first month, for building campaigns, audiences and conversion tracking."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Video production. Agencies that make ads charge anywhere from about $1,000 per video to $10,000 for a fully produced spot."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"New ad versions. Ads wear out as the same people see them again. Ask how many new versions per month the fee includes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Revisions beyond the agreed rounds on each video."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stock footage and music licences, which can add a few hundred dollars a month."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tracking and reporting tools, if the agency passes software costs on to you."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Early exit fees on longer contracts."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"If a quote doesn't mention production at all, assume you will need to supply the videos yourself."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"When an agency is worth it, and when to run ads yourself"}]},{"type":"paragraph","content":[{"type":"text","text":"An agency usually pays for itself when at least two of these are true:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You can spend $1,500 or more a month on ads for at least three months."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You don't have ad videos yet, or the ones you have were made for organic posting."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nobody on your team has set up conversion tracking in Google Ads before."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You sell something with a clear value per customer, so results can be measured in leads or sales."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"If your budget is a few hundred dollars a month, an agency fee will likely cost more than the ads. You'll learn more by running a small campaign yourself in Google Ads, or by paying a freelancer for a one-time setup. "},{"type":"text","text":"MarketerHire","marks":[{"type":"link","attrs":{"href":"https://marketerhire.com/blog/youtube-video-marketing-agency"}}]},{"type":"text","text":" makes a similar point: an agency that takes on an account spending around $1,500 a month is mostly selling its time, because YouTube campaigns need enough volume to learn."}]},{"type":"paragraph","content":[{"type":"text","text":"One rule applies at any budget: the Google Ads account should be in your name. If you part ways, you keep the history, audiences and conversion data."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How to compare agency quotes"}]},{"type":"paragraph","content":[{"type":"text","text":"Get at least three quotes, then put them side by side using the same questions:"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is this price the fee only, or fee plus ad spend?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Which pricing model is it, and what happens to the fee if my ad budget doubles?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How many new ad versions do you test each month?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is video production included? If not, what does one ad video cost?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Who owns the Google Ads account and the YouTube channel?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the minimum contract, and what does it cost to leave early?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Which one or two numbers will you report on? Cost per lead and return on ad spend are more useful than views."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Can you show results from a business like mine, with real numbers and links?"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Run the break-even formula from earlier on any percentage quote, then look at the total for your planned budget, not the headline fee."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"FAQ"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"How much should a small business spend on YouTube ads?"}]},{"type":"paragraph","content":[{"type":"text","text":"Many small businesses start between $100 and $1,000 a month; 53% of businesses in a WebFX survey spent in that range. If you're hiring an agency, budget at least $1,500 a month in ad spend so the campaign has enough data to improve."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Is the ad spend included in the agency's fee?"}]},{"type":"paragraph","content":[{"type":"text","text":"Usually not. Most agencies charge their fee separately, and you pay Google directly for the ads. Always ask, because some quotes combine both."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Is a percentage-of-spend fee a bad deal?"}]},{"type":"paragraph","content":[{"type":"text","text":"Not by itself. It's often cheaper than a flat fee at low budgets and more expensive at high ones. Use the break-even formula to see where your budget falls."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Is there a minimum ad spend on YouTube?"}]},{"type":"paragraph","content":[{"type":"text","text":"Google doesn't set a minimum. Agencies often do, because small budgets don't give them enough data to test and improve."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"How long before YouTube ads show results?"}]},{"type":"paragraph","content":[{"type":"text","text":"Expect the first month to go to setup and early testing. Most agencies and advertisers judge results after about three months of steady spend."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Do YouTube ads agencies make the videos?"}]},{"type":"paragraph","content":[{"type":"text","text":"Some do and some don't. Ask before you sign, since production can cost more than management."}]}]}$g$::jsonb,
  body_html = $g$<p>A YouTube ads agency usually costs $1,000 to $5,000 a month for a small or mid-sized business. That is the agency's fee only. The money you spend on the ads themselves is a separate bill paid to Google.</p><p>In our October 2026 review of publicly listed agency prices, most YouTube ads agencies started between $1,000 and $3,000. Agencies that bill as a share of your budget usually take 10% to 20% of monthly ad spend, and some YouTube specialists quote 15% to 25%.</p><p>Bigger brands that want strategy, ad production and testing in one package often pay $5,000 to $12,000 or more a month on top of ad spend.</p><p>Your own number depends on three things: how the agency charges, how much you plan to spend on ads, and whether you need them to make the videos. Each one is covered below, followed by three sample budgets you can copy.</p><h2>You pay two bills: the agency and Google</h2><p>Every YouTube ads budget splits into two parts. The first is the agency's fee for strategy, setup, targeting, testing and reporting. The second is your ad spend, which goes straight to Google Ads, usually charged to your own card or invoice.</p><p>This is where most quotes get confusing. One agency says "$1,500 a month" and means the fee only. Another says "$5,000 a month" and means fee plus ad spend combined. Before you compare two quotes, ask each agency to split them.</p><p>A few agencies buy the media for you and bill you one total. That can work, but ask to see the Google Ads invoices. Otherwise you can't tell how much of your money reached YouTube.</p><h2>The four ways YouTube ads agencies charge</h2><p>Most agencies use one of four pricing models. Flat monthly retainers are by far the most common. In a <a href="https://www.getcredo.com/guide/digital-marketing-industry-pricing-survey/ppc-pricing/">Credo survey</a> of 146 firms that run paid ads, about 83% billed a flat retainer and about 13% billed only a percentage of spend.</p><table><thead><tr><th>Model</th><th>How it works</th><th>Typical range</th><th>Best for</th></tr></thead><tbody><tr><td>Flat monthly retainer</td><td>Same fee every month, whatever you spend</td><td>$1,000 to $5,000 a month for most small and mid-sized accounts</td><td>Steady budgets, businesses that want a predictable bill</td></tr><tr><td>Percentage of ad spend</td><td>Fee is a share of what you spend that month</td><td>10% to 20% of spend, often with a minimum of about $500</td><td>Accounts spending $10,000+ a month that plan to scale</td></tr><tr><td>Hybrid</td><td>A base fee plus a smaller percentage</td><td>Example: $1,000 base plus 5% of spend</td><td>Budgets that change a lot month to month</td></tr><tr><td>Per project or per video</td><td>One price for a campaign launch or each ad video</td><td>$1,000 to $3,000 per project; $1,500 to $10,000 per produced video</td><td>One-off launches, testing an agency before a retainer</td></tr></tbody></table><p>Ranges come from <a href="https://clicksgeek.com/?p=17034">Clicksgeek</a>, <a href="https://marketerhire.com/blog/youtube-video-marketing-agency">MarketerHire</a> and our October 2026 review of agency prices.</p><p>Performance pricing exists too, where the agency is paid per lead or per sale. It is rare for YouTube because video ads often drive sales that show up later through search or direct visits, which makes the credit hard to agree on.</p><h3>Flat fee or percentage: the break-even point</h3><p>To compare a flat quote with a percentage quote, divide the flat fee by the percentage:</p><pre><code>\text{Break-even ad spend} = \frac{\text{flat monthly fee}}{\text{percentage rate}}</code></pre><p>Say Agency A quotes $1,500 a month and Agency B quotes 15% of spend. $1,500 divided by 0.15 is $10,000. Below $10,000 a month in ad spend, Agency B costs less. Above it, Agency A does.</p><p>Keep one thing in mind with percentage pricing: the agency earns more when you spend more, whether or not the extra spend is profitable. That doesn't make it a bad model, but it means you should agree on a target cost per lead or return on ad spend before you raise the budget.</p><p>Starting prices are a floor. Your quote will rise with ad spend, the number of ad videos you need, and how many campaigns run at once. For a wider sample, <a href="https://clutch.co/agencies/ppc/youtube">Clutch</a> reports minimum project sizes from $1,000 to over $50,000 across thousands of YouTube advertising firms, with $100 to $149 an hour as the most common rate.</p><h2>What the ads themselves cost</h2><p>YouTube ads are usually cheap per view. Across industries, the average cost per view is about $0.026 and the average cost per 1,000 impressions is about $3.53, according to Mega Digital's benchmark data. Competitive niches cost more: healthcare and insurance had the highest average view cost in the same data, at $0.071.</p><table><thead><tr><th>Ad format</th><th>How you pay</th><th>Typical cost</th></tr></thead><tbody><tr><td>Skippable in-stream</td><td>Per view (30 seconds watched, the full ad if shorter, or a click)</td><td>$0.02 to $0.30 per view</td></tr><tr><td>Non-skippable in-stream</td><td>Per 1,000 impressions</td><td>$6 to $10 CPM</td></tr><tr><td>Bumper (6 seconds)</td><td>Per 1,000 impressions</td><td>$10 to $20 CPM</td></tr><tr><td>In-feed video</td><td>Per view (thumbnail click)</td><td>About $0.10 per view</td></tr><tr><td>Shorts</td><td>Per 1,000 impressions</td><td>About $4 CPM</td></tr><tr><td>Masthead (top of homepage)</td><td>Reserved through Google sales</td><td>$300,000 to $1M+</td></tr></tbody></table><p>Sources: <a href="https://megadigital.ai/en/blog/youtube-ads-cost">Mega Digital cost guide</a>, <a href="https://joinbrands.com/blog/how-much-do-youtube-ads-cost/">JoinBrands</a>, <a href="https://topgrowthmarketing.com/youtube-ads-cost/">Top Growth Marketing</a>.</p><p>What most small businesses actually spend is modest. In a <a href="https://www.webfx.com/social-media/pricing/how-much-does-youtube-advertising-cost">WebFX survey</a> of 270 marketers, 53% of businesses spent between $101 and $1,000 a month on YouTube ads.</p><p>A cheap view isn't automatically a good one. Work backward from what a customer is worth. If you can afford to pay $40 to win a customer and 0.5% of viewers convert, you can pay up to $0.20 a view and still make your target.</p><h2>Three sample monthly budgets</h2><p>These are worked examples built from the ranges above, not quotes. Use them to sanity-check what an agency sends you.</p><table><thead><tr><th>Scenario</th><th>Ad spend</th><th>Agency fee</th><th>Ad videos</th><th>Total per month</th></tr></thead><tbody><tr><td>Local business testing YouTube (clinic, law firm, trades)</td><td>$1,500</td><td>$1,000 flat retainer</td><td>Uses one existing video</td><td>$2,500</td></tr><tr><td>Growing e-commerce or SaaS brand</td><td>$10,000</td><td>$1,500 (15% of spend)</td><td>2 new ads at about $1,000 each</td><td>$13,500</td></tr><tr><td>Established brand running several campaigns</td><td>$50,000</td><td>$4,500 (hybrid: $2,000 base plus 5%)</td><td>About $5,000 of new creative</td><td>$59,500</td></tr></tbody></table><p>In the first scenario, the agency fee is two-thirds of the ad spend. That ratio is normal for small tests, but it means you're mostly paying for setup and learning. Plan to run it for at least three months before you judge results.</p><p>In the third, the fee is under 10% of the total. Past a certain size, the cost that matters most is ad spend that isn't working, so the agency's testing process matters more than its fee.</p><h2>Extra costs to ask about</h2><p>The monthly fee rarely covers everything. Ask each agency whether these are included:</p><ul><li><p>Setup or onboarding fees in the first month, for building campaigns, audiences and conversion tracking.</p></li><li><p>Video production. Agencies that make ads charge anywhere from about $1,000 per video to $10,000 for a fully produced spot.</p></li><li><p>New ad versions. Ads wear out as the same people see them again. Ask how many new versions per month the fee includes.</p></li><li><p>Revisions beyond the agreed rounds on each video.</p></li><li><p>Stock footage and music licences, which can add a few hundred dollars a month.</p></li><li><p>Tracking and reporting tools, if the agency passes software costs on to you.</p></li><li><p>Early exit fees on longer contracts.</p></li></ul><p>If a quote doesn't mention production at all, assume you will need to supply the videos yourself.</p><h2>When an agency is worth it, and when to run ads yourself</h2><p>An agency usually pays for itself when at least two of these are true:</p><ul><li><p>You can spend $1,500 or more a month on ads for at least three months.</p></li><li><p>You don't have ad videos yet, or the ones you have were made for organic posting.</p></li><li><p>Nobody on your team has set up conversion tracking in Google Ads before.</p></li><li><p>You sell something with a clear value per customer, so results can be measured in leads or sales.</p></li></ul><p>If your budget is a few hundred dollars a month, an agency fee will likely cost more than the ads. You'll learn more by running a small campaign yourself in Google Ads, or by paying a freelancer for a one-time setup. <a href="https://marketerhire.com/blog/youtube-video-marketing-agency">MarketerHire</a> makes a similar point: an agency that takes on an account spending around $1,500 a month is mostly selling its time, because YouTube campaigns need enough volume to learn.</p><p>One rule applies at any budget: the Google Ads account should be in your name. If you part ways, you keep the history, audiences and conversion data.</p><h2>How to compare agency quotes</h2><p>Get at least three quotes, then put them side by side using the same questions:</p><ol><li><p>Is this price the fee only, or fee plus ad spend?</p></li><li><p>Which pricing model is it, and what happens to the fee if my ad budget doubles?</p></li><li><p>How many new ad versions do you test each month?</p></li><li><p>Is video production included? If not, what does one ad video cost?</p></li><li><p>Who owns the Google Ads account and the YouTube channel?</p></li><li><p>What is the minimum contract, and what does it cost to leave early?</p></li><li><p>Which one or two numbers will you report on? Cost per lead and return on ad spend are more useful than views.</p></li><li><p>Can you show results from a business like mine, with real numbers and links?</p></li></ol><p>Run the break-even formula from earlier on any percentage quote, then look at the total for your planned budget, not the headline fee.</p><h2>FAQ</h2><h3>How much should a small business spend on YouTube ads?</h3><p>Many small businesses start between $100 and $1,000 a month; 53% of businesses in a WebFX survey spent in that range. If you're hiring an agency, budget at least $1,500 a month in ad spend so the campaign has enough data to improve.</p><h3>Is the ad spend included in the agency's fee?</h3><p>Usually not. Most agencies charge their fee separately, and you pay Google directly for the ads. Always ask, because some quotes combine both.</p><h3>Is a percentage-of-spend fee a bad deal?</h3><p>Not by itself. It's often cheaper than a flat fee at low budgets and more expensive at high ones. Use the break-even formula to see where your budget falls.</p><h3>Is there a minimum ad spend on YouTube?</h3><p>Google doesn't set a minimum. Agencies often do, because small budgets don't give them enough data to test and improve.</p><h3>How long before YouTube ads show results?</h3><p>Expect the first month to go to setup and early testing. Most agencies and advertisers judge results after about three months of steady spend.</p><h3>Do YouTube ads agencies make the videos?</h3><p>Some do and some don't. Ask before you sign, since production can cost more than management.</p>$g$,
  content_updated_at = now()
where slug = 'youtube-ads-agency-cost'
  and (length(body_json::text) - length(replace(body_json::text, 'https://marketerhire.com/blog/youtube-video-marketing-agency', ''))) / 60 = 1;

